// Global initializations moved here from global-script.js
// Минимальная инициализация проекта: no-js -> js, vh fix, lazy-bg, theme switcher

function applyJsClass() {
  document.documentElement.className = document.documentElement.className.replace('no-js', 'js');
}

function setupVhFix() {
  const setVh = () => {
    const vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
  };
  setVh();
  window.addEventListener('resize', setVh);
}

function canUseWebp() {
  const elem = document.createElement('canvas');
  return !!(elem.getContext && elem.getContext('2d')) &&
    elem.toDataURL('image/webp').indexOf('data:image/webp') === 0;
}

function loadBackgroundImage(element, fastScroll) {
  const isWebpSupported = canUseWebp();
  const bgImage = isWebpSupported ? element.getAttribute('data-bg-webp') : element.getAttribute('data-bg');
  if (!bgImage) return;
  element.style.backgroundImage = `url(${bgImage})`;
  element.removeAttribute('data-bg');
  element.removeAttribute('data-bg-webp');

  const speed = parseFloat(element.getAttribute('data-bg-speed')) || 1;
  const finalSpeed = fastScroll ? speed * 0.5 : speed;

  requestAnimationFrame(() => {
    element.style.transition = `opacity ${finalSpeed}s ease-out`;
    element.style.opacity = 1;
  });
}

function observeLazyLoad() {
  const lazyElements = document.querySelectorAll('[data-bg], [data-bg-webp]');
  lazyElements.forEach(el => {
    el.style.opacity = '0';
    el.style.willChange = 'opacity';
  });

  let lastTime = performance.now();
  let lastScrollY = window.scrollY;

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries, obs) => {
      const now = performance.now();
      const deltaY = Math.abs(window.scrollY - lastScrollY);
      const deltaT = now - lastTime;
      const speed = deltaY / (deltaT || 1);
      const fastScroll = speed > 1;

      entries.forEach(entry => {
        if (entry.isIntersecting) {
          loadBackgroundImage(entry.target, fastScroll);
          obs.unobserve(entry.target);
        }
      });

      lastTime = now;
      lastScrollY = window.scrollY;
    }, { rootMargin: '0px', threshold: 0.1 });

    lazyElements.forEach(el => observer.observe(el));
  } else {
    lazyElements.forEach(el => loadBackgroundImage(el, false));
  }
}

// Theme switcher (kept minimal)
function initThemeSwitcher() {
  const STORAGE_KEY = 'theme';
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
  let transitionTimeout;

  function getPreferredTheme() {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'dark' || saved === 'light') return saved;
    return prefersDark.matches ? 'dark' : 'light';
  }

  function applyTheme(theme, smooth = false) {
    if (smooth) {
      clearTimeout(transitionTimeout);
      document.documentElement.classList.add('theme-transition');
      transitionTimeout = setTimeout(() => {
        document.documentElement.classList.remove('theme-transition');
      }, 350);
    }
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem(STORAGE_KEY, theme);
  }

  function applySystemTheme(smooth = false) {
    const systemTheme = prefersDark.matches ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', systemTheme);
    if (smooth) {
      clearTimeout(transitionTimeout);
      document.documentElement.classList.add('theme-transition');
      transitionTimeout = setTimeout(() => {
        document.documentElement.classList.remove('theme-transition');
      }, 350);
    }
  }

  function toggleTheme() {
    const current = document.documentElement.getAttribute('data-theme') || 'light';
    const next = current === 'dark' ? 'light' : 'dark';
    applyTheme(next, true);
  }

  window.addEventListener('storage', (e) => {
    if (e.key === STORAGE_KEY) {
      if (e.newValue === null) applySystemTheme(true);
      else if (e.newValue === 'dark' || e.newValue === 'light') applyTheme(e.newValue, true);
    }
  });

  document.addEventListener('DOMContentLoaded', () => {
    const theme = getPreferredTheme();
    applyTheme(theme);
    requestAnimationFrame(() => document.documentElement.classList.remove('no-transition'));
    document.getElementById('toggle-theme')?.addEventListener('click', toggleTheme);
    prefersDark.addEventListener('change', () => {
      if (!localStorage.getItem(STORAGE_KEY)) applySystemTheme(true);
    });
  });
}

// Инициализация всех глобальных вещей
function initGlobal() {
  applyJsClass();
  setupVhFix();
  document.addEventListener('DOMContentLoaded', observeLazyLoad);
  initThemeSwitcher();
}

// Выполняем init сразу — индексный файл будет выполняться при подключении/включении в бандл
initGlobal();

